#[derive(Debug, Clone, PartialEq)]
struct DType {
    kind: char,
    precedence: u8,
}

fn find_max_precedence_type(types: Vec<DType>) -> DType {
    // Start with the first dtype as the maximum
    let mut max_dtype = types[0].clone();

    for dtype in types.iter() {
        if dtype.precedence > max_dtype.precedence {
            max_dtype = dtype.clone();
        }
    }

    max_dtype
}

fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    let max_array_dtype = if !array_types.is_empty() {
        Some(find_max_precedence_type(array_types))
    } else {
        None
    };

    let max_scalar_dtype = if !scalar_types.is_empty() {
        Some(find_max_precedence_type(scalar_types))
    } else {
        None
    };

    match (max_array_dtype, max_scalar_dtype) {
        (Some(array_dtype), Some(scalar_dtype)) => {
            if array_dtype.kind == scalar_dtype.kind {
                // Return the maximum from the array collection
                Some(array_dtype)
            } else {
                // Return the maximum from the scalar collection
                Some(scalar_dtype)
            }
        }
        (Some(array_dtype), None) => Some(array_dtype),
        (None, Some(scalar_dtype)) => Some(scalar_dtype),
        (None, None) => None, // This case should not happen due to the problem constraints
    }
}

// Example usage
fn main() {
    let array_types = vec![
        DType { kind: 'i', precedence: 3 },
        DType { kind: 'f', precedence: 9 },
    ];
    
    let scalar_types = vec![
        DType { kind: 'i', precedence: 2 },
        DType { kind: 'b', precedence: 0 },
    ];

    let max_array_dtype = find_max_precedence_type(array_types.clone());
    println!("Max Array DType: {:?}", max_array_dtype);

    let common_dtype = find_common_type(array_types, scalar_types);
    println!("Common DType: {:?}", common_dtype);
}